"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { CopyButton } from "@/components/ui/source"

/** What runs a package without installing it, per package manager. */
const RUNNERS = { npm: "npx", pnpm: "pnpm dlx", yarn: "yarn", bun: "bunx --bun" } as const
type Runner = keyof typeof RUNNERS
const STORE = "0db-runner"

// Every command line on the page shares one choice, and the next visit remembers it.
let chosen: Runner | undefined
const heard = new Set<() => void>()
const isRunner = (v: unknown): v is Runner => typeof v === "string" && v in RUNNERS
function current(): Runner {
  if (chosen) return chosen
  try {
    const stored = localStorage.getItem(STORE)
    if (isRunner(stored)) return stored
  } catch {} // private mode: the choice lasts the visit
  return "npm"
}
function subscribe(notify: () => void) {
  heard.add(notify)
  addEventListener("storage", notify)
  return () => {
    heard.delete(notify)
    removeEventListener("storage", notify)
  }
}
function choose(next: Runner) {
  chosen = next
  try {
    localStorage.setItem(STORE, next)
  } catch {}
  heard.forEach((notify) => notify())
}

type CommandLineProps = Omit<React.ComponentProps<"figure">, "children"> & {
  /** The command, without a runner when `runner` is set: "shadcn@latest add https://…/button.json". */
  command: string
  /** Run it through a package manager the reader picks (npx, pnpm dlx, yarn, bunx). The pick is shared and remembered. */
  runner?: boolean
  /** The part that's the reader's, set in italic: an item's name inside a URL. */
  emphasis?: string
  /**
   * line (the default): one line on a baseline. parsed: each word glossed beneath in small type, on a short
   * rule under the word. synopsis: the emphasis is a blank the reader fills in, and Copy copies what they wrote.
   */
  variant?: "line" | "parsed" | "synopsis"
  /** parsed: a gloss for each word of the command, in order; leave one empty to skip that word. */
  glosses?: string[]
  /** synopsis: names the blank for assistive tech, e.g. "Item name". */
  blank?: string
}

/**
 * One line to type, set on a baseline like a field already filled in. The runner and the address
 * recede to pencil; the words that matter are ink, and the part that's yours is italic.
 * Copying draws the baseline in the accent.
 */
function CommandLine({ command, runner = false, emphasis, variant = "line", glosses, blank = "Your part", className, ...props }: CommandLineProps) {
  const pick = React.useSyncExternalStore(subscribe, current, () => "npm" as Runner)
  const prefix = runner ? `${RUNNERS[pick]} ` : ""
  const [copied, setCopied] = React.useState(0)
  const [filled, setFilled] = React.useState(emphasis ?? "")
  const synopsis = variant === "synopsis" && !!emphasis
  const typed = synopsis ? command.replace(emphasis!, filled.trim() || emphasis!) : command
  const yours = (part: string) =>
    synopsis ? (
      <input
        className="db-command-line-blank"
        aria-label={blank}
        value={filled}
        placeholder={part}
        size={Math.max(filled.length, part.length, 1)}
        spellCheck={false}
        autoCapitalize="off"
        autoComplete="off"
        onChange={(e) => setFilled(e.target.value.replace(/\s/g, ""))}
      />
    ) : (
      <em className="db-command-line-yours">{part}</em>
    )
  const parsed = variant === "parsed" && glosses?.length
  return (
    <figure data-slot="command-line" data-variant={variant} className={cn("db-command-line", className)} {...props}>
      {runner ? (
        <RadioGroup aria-label="Package manager" className="db-command-line-runners" value={pick} onValueChange={(v) => isRunner(v) && choose(v)}>
          {(Object.keys(RUNNERS) as Runner[]).map((r) => (
            <RadioGroupItem key={r} value={r}>
              {r}
            </RadioGroupItem>
          ))}
        </RadioGroup>
      ) : null}
      <div key={copied} data-copied={copied || undefined} className="db-command-line-row">
        <code data-slot="command-line-text" className="db-command-line-text" dir="ltr">
          {prefix ? <span className="db-command-line-quiet">{prefix}</span> : null}
          {words(command, emphasis, yours, parsed ? glosses : undefined)}
        </code>
        {parsed ? (
          <span className="db-sr">
            {command
              .split(/\s+/)
              .map((w, i) => (glosses[i] ? `${w}: ${glosses[i]}` : ""))
              .filter(Boolean)
              .join(". ")}
          </span>
        ) : null}
        <CopyButton text={prefix + typed} onCopied={() => setCopied((c) => c + 1)} />
      </div>
    </figure>
  )
}

/** Addresses recede, all but the emphasis; a long one breaks after a slash. */
function words(command: string, emphasis: string | undefined, yours: (part: string) => React.ReactNode, glosses?: string[]) {
  let n = -1
  return command.split(/(\s+)/).map((word, i) => {
    if (/^\s+$/.test(word)) return <React.Fragment key={i}>{word}</React.Fragment>
    n++
    const set = address(word, emphasis, yours)
    // parsed: the word stands over a short rule, its gloss hung beneath (aria-hidden; the list is read after).
    if (glosses?.[n])
      return (
        <span key={i} className="db-command-line-word">
          <span className="db-command-line-said">{set}</span>
          <span className="db-command-line-gloss" aria-hidden="true">
            {glosses[n]}
          </span>
        </span>
      )
    return <React.Fragment key={i}>{set}</React.Fragment>
  })
}

function address(word: string, emphasis: string | undefined, yours: (part: string) => React.ReactNode) {
  const at = emphasis ? word.lastIndexOf(emphasis) : -1
  if (!/^[a-z]+:\/\//.test(word)) {
    if (at < 0) return word
    return (
      <>
        {word.slice(0, at)}
        {yours(emphasis!)}
        {word.slice(at + emphasis!.length)}
      </>
    )
  }
  const before = at < 0 ? word : word.slice(0, at)
  return (
    <span className="db-command-line-quiet">
      {breakable(before)}
      {at < 0 ? null : (
        // The name and what follows it (".json") hold together: no line starts with ".json" or "card".
        <span className="db-command-line-whole">
          {yours(emphasis!)}
          {word.slice(at + emphasis!.length)}
        </span>
      )}
    </span>
  )
}

// A break may follow a slash, but never falls inside "//".
const breakable = (s: string) =>
  s.split(/(?<=\/)(?!\/)/).map((part, i) => (
    <React.Fragment key={i}>
      {i ? <wbr /> : null}
      {part}
    </React.Fragment>
  ))

export { CommandLine, type CommandLineProps }

@layer components {
  /* ── db-command-line ── one line to type, on a baseline like a field already filled in.
     The runner and the address recede to pencil; the part that's yours is italic.
     Copying draws the baseline in the accent, left to right. */
  .db-command-line { margin: 0; min-width: 0; }
  .db-command-line-runners.db-choice {
    font-size: var(--db-pp); line-height: var(--db-pp-lh); column-gap: var(--db-space-4);
    padding-block-end: var(--db-space-3); margin-block-end: var(--db-space-3);
  }
  .db-command-line-row {
    position: relative; display: flex; align-items: baseline; gap: var(--db-space-5);
    padding-block-end: var(--db-space-3);
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
  }
  .db-command-line-row::after {
    content: ""; position: absolute; inset-inline: 0; inset-block-end: 0; block-size: var(--db-stroke);
    background: var(--db-accent); transform-origin: 0 0; scale: 0 1; opacity: 0; pointer-events: none;
  }
  .db-command-line-row:is([dir="rtl"], [dir="rtl"] *)::after { transform-origin: 100% 0; }
  .db-command-line-row[data-copied]::after { animation: db-command-line-draw var(--db-adagio) var(--db-exhale) both; }
  @keyframes db-command-line-draw {
    0%   { opacity: 1; scale: 0 1; }
    45%  { opacity: 1; scale: 1 1; }
    100% { opacity: 0; scale: 1 1; }
  }
  .db-command-line-text {
    flex: 1; min-width: 0; padding-inline-start: 1.5em; text-indent: -1.5em; overflow-wrap: break-word;
    font-family: var(--db-voice); font-size: var(--db-mp); line-height: var(--db-mp-lh); letter-spacing: var(--db-mp-tr);
    font-stretch: 94%; color: var(--db-ink);
  }
  .db-command-line-quiet { color: var(--db-pencil); }
  /* The name and its ".json" move to a new line whole; a name wider than the line itself breaks after a hyphen. */
  .db-command-line-whole { display: inline-block; max-inline-size: 100%; text-indent: 0; }
  .db-command-line-yours {
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-stretch: 100%;
    font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; color: var(--db-ink);
  }
  .db-command-line-row > .db-source-copy { flex: none; margin: 0; font-size: var(--db-pp); }

  /* parsed: the interlinear gloss (a linguist's word-by-word gloss; the dictionary entry of "the uncreative",
     the part of speech set small under the word). Each glossed word stands over a short rule, its gloss hung
     beneath in small type; the words keep one baseline and the line teaches itself. Pointing at a word inks
     its rule and its gloss. */
  .db-command-line[data-variant="parsed"] .db-command-line-text { line-height: calc(var(--db-mp-lh) + 0.2); }
  .db-command-line-word { display: inline-flex; flex-direction: column; max-inline-size: 100%; vertical-align: baseline; text-indent: 0; }
  .db-command-line-said { align-self: flex-start; padding-block-end: 0.1em; border-block-end: var(--db-hairline) solid var(--db-rule-strong); transition: border-color var(--db-allegro); }
  .db-command-line-gloss {
    padding-block: var(--db-space-1) var(--db-space-2); padding-inline-end: var(--db-space-4); font-family: var(--db-voice); font-stretch: 100%;
    font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); color: var(--db-pencil);
    white-space: nowrap; transition: color var(--db-allegro);
  }
  .db-command-line-word:hover > .db-command-line-said, .db-command-line[data-force~="hover"] .db-command-line-word:first-child > .db-command-line-said { border-block-end-color: var(--db-ink); }
  .db-command-line-word:hover > .db-command-line-gloss, .db-command-line[data-force~="hover"] .db-command-line-word:first-child > .db-command-line-gloss { color: var(--db-ink); }

  /* synopsis: a manual page's synopsis, where the words you replace are set in italic. Here that part is a
     blank you write in, in your italic; it grows with what you write, and Copy copies your line. Focus draws
     the accent under your part only. */
  .db-command-line-blank {
    appearance: none; margin: 0; padding: 0 0.05em; border: 0; border-radius: 0; background: none; outline: 0;
    field-sizing: content; min-inline-size: 2ch;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-stretch: 100%;
    font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; letter-spacing: 0; color: var(--db-ink);
    box-shadow: inset 0 calc(-1 * var(--db-hairline)) 0 var(--db-ink);
    transition: box-shadow var(--db-allegro);
  }
  .db-command-line[data-force~="focus"] { outline: none; }
  .db-command-line-blank::placeholder { color: var(--db-pencil); opacity: 1; }
  .db-command-line-blank:focus-visible, .db-command-line[data-force~="focus"] .db-command-line-blank { box-shadow: inset 0 calc(-1 * var(--db-stroke)) 0 var(--db-accent); }

  @media (forced-colors: active) {
    .db-command-line-blank:focus-visible { outline: 2px solid Highlight; }
    .db-command-line-said { border-block-end-color: CanvasText; }
  }
}
